CREATE FUNCTION [dbo].[Q_LIST_DAYLY_1]  (@DT1 BIGINT,  @DT2 BIGINT)  RETURNS Table  AS RETURN ( SELECT        Q_LIST_FROOSH_DAYLY.DATE_N, Q_LIST_FROOSH_DAYLY.NUMBER, Q_LIST_FROOSH_DAYLY.SumOfM_NAGHD,  Q_LIST_FROOSH_DAYLY.SumOfMABL_VAR, Q_LIST_FROOSH_DAYLY.SumOfMABL_HAV, Q_LIST_FROOSH_DAYLY.SumOfMABL_HAZ,  Q_LIST_FROOSH_DAYLY.SumOfTAKHFIF, Q_LIST_FROOSH_DAYLY.hes, Q_LIST_FROOSH_DAYLY.NAME, Q_LIST_FROOSH_DAYLY.DEPATMAN,  Q_LIST_FROOSH_DAYLY.USER_NAME, Q_LIST_FROOSH_DAYLY.SHIFT, dbo.SHIFT.SHNAME, dbo.DEPART.DEPNAME,  RIGHT(Q_LIST_FROOSH_DAYLY.USER_NAME, LEN(Q_LIST_FROOSH_DAYLY.USER_NAME) - 2) AS USS, ' ' AS kk, ISNULL(Q_LIST_FCT.SumOfMABL_K, 0)  AS jamf, ISNULL(Q_LIST_FCT.SIMBAA, 0) AS simbaa, ISNULL(Q_LIST_FROOSH_DAYLY_CHK.SumOfMABL, 0) AS jamch, Q_LIST_FROOSH_DAYLY.ECODE, Q_LIST_FROOSH_DAYLY.SMBAA , IsNull(Q_LIST_FCT.SumOfMABL_K, 0)  + Q_LIST_FROOSH_DAYLY.SMBAA + Q_LIST_FROOSH_DAYLY.SumOfMABL_HAZ - Q_LIST_FROOSH_DAYLY.SumOfTAKHFIF - Q_LIST_FROOSH_DAYLY.SumOfM_NAGHD   - Q_LIST_FROOSH_DAYLY.SumOfMABL_VAR - Q_LIST_FROOSH_DAYLY.SumOfMABL_HAV - ISNULL(Q_LIST_FROOSH_DAYLY_CHK.SumOfMABL, 0)  AS mand, Q_LIST_FROOSH_DAYLY.MOLAH, Q_LIST_FROOSH_DAYLY.TEL, Q_LIST_FROOSH_DAYLY.CUST_KIND, dbo.CUSTKIND.CUSTKNAME,  Q_LIST_FROOSH_DAYLY.MOIN_HAV, Q_LIST_FROOSH_DAYLY.MOIN_HAZ, Q_LIST_FROOSH_DAYLY.MOIN_VAR, dbo.HEAD_LST.DATE_N AS date_h,  dbo.HEAD_LST.DATE_N - Q_LIST_FROOSH_DAYLY.DATE_N AS ddf, Q_LIST_FROOSH_DAYLY.NUMBER1, Q_LIST_FROOSH_DAYLY.TICMBAA,  Q_LIST_FROOSH_DAYLY.N_S, Q_LIST_FROOSH_DAYLY.VAS, Q_LIST_FROOSH_DAYLY.MAS, Q_LIST_FROOSH_DAYLY.TAH, dbo.HEAD_LST.ANBAR, Q_LIST_FROOSH_DAYLY.MOIN_KHF, Q_LIST_FROOSH_DAYLY.ANBARF, Q_LIST_FROOSH_DAYLY.SHARAYET, Q_LIST_FROOSH_DAYLY.SGN1,  Q_LIST_FROOSH_DAYLY.SGN2, Q_LIST_FROOSH_DAYLY.SGN3, Q_LIST_FROOSH_DAYLY.SGN4, Q_LIST_FROOSH_DAYLY.HMBAA,  Q_LIST_FROOSH_DAYLY.TAMIR, Q_LIST_FROOSH_DAYLY.TKHF, Q_LIST_FROOSH_DAYLY.SADER, Q_LIST_FROOSH_DAYLY.ARZD,  Q_LIST_FROOSH_DAYLY.ARZKIND, Q_LIST_FROOSH_DAYLY.JAY, Q_LIST_FROOSH_DAYLY.MODAT_PPID, Q_LIST_FROOSH_DAYLY.PEPID,  Q_LIST_FROOSH_DAYLY.PEID , dbo.CUST_HESAB.MCODEM, dbo.CUST_HESAB.MOBILE, dbo.CUST_HESAB.OSTANID, dbo.CUST_HESAB.SHAHRID FROM            dbo.DEPART INNER JOIN  dbo.Q_LIST_FROOSH_DAYLY(@DT1, @DT2) AS Q_LIST_FROOSH_DAYLY ON dbo.DEPART.DEPATMAN = Q_LIST_FROOSH_DAYLY.DEPATMAN INNER JOIN  dbo.SHIFT ON Q_LIST_FROOSH_DAYLY.SHIFT = dbo.SHIFT.SHIFT_ID INNER JOIN  dbo.CUSTKIND ON Q_LIST_FROOSH_DAYLY.CUST_KIND = dbo.CUSTKIND.CUST_COD INNER JOIN  dbo.HEAD_LST ON Q_LIST_FROOSH_DAYLY.NUMBER = dbo.HEAD_LST.NUMBER AND Q_LIST_FROOSH_DAYLY.TAG - 11 = dbo.HEAD_LST.TAG INNER JOIN  dbo.CUST_HESAB ON Q_LIST_FROOSH_DAYLY.hes = dbo.CUST_HESAB.hes LEFT OUTER JOIN  dbo.Q_LIST_FCT(@DT1, @DT2) AS Q_LIST_FCT ON Q_LIST_FROOSH_DAYLY.TAG = Q_LIST_FCT.TAG AND  Q_LIST_FROOSH_DAYLY.NUMBER = Q_LIST_FCT.NUMBER LEFT OUTER JOIN  dbo.Q_LIST_FROOSH_DAYLY_CHK(@DT1, @DT2) AS Q_LIST_FROOSH_DAYLY_CHK ON  Q_LIST_FROOSH_DAYLY.TAG = Q_LIST_FROOSH_DAYLY_CHK.TAG AND  Q_LIST_FROOSH_DAYLY.NUMBER = Q_LIST_FROOSH_DAYLY_CHK.NUMBER WHERE        (Q_LIST_FROOSH_DAYLY.DATE_N BETWEEN @DT1 AND @DT2))
